WITH enriched AS (SELECT id, store_id, product_id, sale_date, revenue, LAG(revenue) OVER (PARTITION BY store_id ORDER BY revenue, id) AS prev_revenue, LEAD(revenue) OVER (PARTITION BY store_id ORDER BY revenue, id) AS next_revenue, LAG(units) OVER (PARTITION BY store_id ORDER BY revenue, id) AS prev_units, LEAD(units) OVER (PARTITION BY store_id ORDER BY revenue, id) AS next_units, ROW_NUMBER() OVER (PARTITION BY store_id ORDER BY revenue, id) AS row_seq FROM store_sales) SELECT DATE_TRUNC('QUARTER', sale_date) AS quarter_start, product_id, MIN(row_seq) AS min_row_seq, PERCENTILE_APPROX(next_units, 0.9) AS next_units_p90, ROUND(AVG(next_revenue), 2) AS avg_next_revenue, PERCENTILE_APPROX(next_units, 0.5) AS next_units_p50 FROM enriched GROUP BY 1, 2 HAVING next_units_p50 < 1000000 ORDER BY next_units_p50 DESC NULLS LAST;
